-- ============================================================
-- Pro100Practice -- Notion Daily Tracker import (sessions)
-- ============================================================
-- Source: Notion "Guitar Daily Tracker", 108 rows, 2025-08-19 -> 2026-08-02.
-- All rows tagged source='notion_import'. Session blocks are inserted
-- separately in notion-import-blocks.sql.
--
-- Explicit UUIDs are generated here (not gen_random_uuid()) so the
-- same session id can be reused in both INSERT statements below.
-- ============================================================

insert into sessions (id, user_id, session_date, total_minutes, comment, source)
select v.id, u.id, v.session_date, v.total_minutes, v.comment, 'notion_import'
from (select 'pro100seva@gmail.com'::text as email) e
join auth.users u on u.email = e.email,
lateral (values
  ('342eb24a-8a76-475d-a8e3-ebb6d5b8f12f'::uuid, '2025-08-19'::date, 15, E'Прервался на книжный клуб.'),
  ('1e8849fc-deaa-4849-a2cc-29b9e7e9faa1'::uuid, '2025-08-20'::date, 90, E'Начал разучивать Bubble Dream.'),
  ('ba6f9c8b-53d0-43e3-a181-f257793a4def'::uuid, '2025-08-21'::date, 45, E'Устаёт правое плечо; пальцы правой руки трутся о струны; надо заниматься в правильной посадке.'),
  ('7f43655d-fd14-4f01-9b82-c5bdd935e1de'::uuid, '2025-08-22'::date, 45, E'Путаюсь в перехода с триолей на шестнадцатые и обратно.'),
  ('8a0399e8-b0cd-4a27-97ca-6005599409be'::uuid, '2025-08-23'::date, 45, E'При ровной посадке примерно в середине 45-минутной практики хочется поменять ногу; стало проще переходить между разными ритмами, когда начал считать про себя.'),
  ('8c1b1d46-d590-49b8-85ed-dbf89d4761c4'::uuid, '2025-08-24'::date, 80, E'Вышел на 80 бпм шестнадцатыми (арпеджио и хроматика) — чувствую себя неплохо, но нужно продолжать заниматься.'),
  ('8fe86a7f-3521-411d-94e6-02dc0d6294c6'::uuid, '2025-08-25'::date, 80, E'Устали пальцы на упражнении с легато (по три ноты на струну, До мажорная гамма).'),
  ('b2857257-909a-4c4c-b222-afb71ef7770f'::uuid, '2025-08-26'::date, 60, E'Чуть увереннее стали легато — видимо мышцы укрепляются.'),
  ('5facf792-f274-4d3a-8c91-a55f4f3ea73a'::uuid, '2025-08-27'::date, 45, E'Вышел на 100% Bubble Dream - пока есть трудности с пнереходом между частями, но в целом неплохо. Нужно отработать интервальные слайды.'),
  ('91fbd151-f539-4419-9a6f-c7e4a03b3add'::uuid, '2025-08-28'::date, 40, E'Не откладывай первую практику с утра'),
  ('8d9345fd-7aab-417d-948f-514bd3703262'::uuid, '2025-08-29'::date, 65, E'На 80-90 бпм в хроматическом упражнении будто еложу по струнам, атака смазана, иногда играю не ровнор 16-ми; Вивальди рулит!!!'),
  ('7e1d1abd-6003-474f-a40d-e7bd3030bd54'::uuid, '2025-09-01'::date, 10, E'Немного прогнал упражнения, чтобы пальцы не забывали'),
  ('12e3dae3-d479-4da4-8268-7318f81ea0e4'::uuid, '2025-09-04'::date, 30, E'Полчаса, чтобы не откатывать сильно прогресс. Занимался на своей акустике, большее расстояние между струнами добавляет сложности'),
  ('60e4ea54-7f3a-4c38-8f34-f63521f5bf1c'::uuid, '2025-09-08'::date, 45, E'Интересное упражнение на слайды; немного нужно “закольцевать” упражнение на тэппинг; чуть устала левая рука в районе большого пальца во время игры Bubble'),
  ('d833edf6-3d6a-4d06-80d3-530235984a78'::uuid, '2025-09-09'::date, 80, E'Левая рука уже в норме; всё ещё есть “еложение” нот при хроматике на 90 бпм; погонял Героев'),
  ('d5e43c97-6773-45aa-820b-b647b957ee9b'::uuid, '2025-09-10'::date, 45, E'На импровизации не особо интересные линии у меня получаются; пора двигаться дальше с Bubble Dream, либо уже начать учить Nick’a Johnston’a'),
  ('6672aa25-1b2f-4a31-a587-245afb3946e7'::uuid, '2025-09-11'::date, 65, E'Начал “снимать” Remarkably Human — я в восторге!'),
  ('0c729e7d-c5f5-4056-a97f-26354daa17fe'::uuid, '2025-09-12'::date, 90, E'Хроматика похрамывает на 90+; импровизация просто какое-то лабание; Remarkably Human — ремаркабли брилиант!'),
  ('92150179-77db-441e-b3d2-b63072214aa6'::uuid, '2025-09-13'::date, 75, E'Упражнение “паук” действительно помогает — буду теперь его делать на блоке Разминки вместе с хроматикой; заигрался с Remarkably Human — надо кокретно его разобрать'),
  ('6571f40f-da13-4f00-ae80-bf0b49b97c8d'::uuid, '2025-09-14'::date, 70, E'Хроматика с пауком всё же помогают; активно отрабатываю соло на Heroes Don’t Die On Toilets уже несколько дней подряд, прогресс идёт, думаю на следующем живом выступлении будет лучше намного чем в предыдущие разы'),
  ('06c449c7-29fe-424b-ac98-ca3583fb6817'::uuid, '2025-09-15'::date, 120, E'“Паук” - хорошо; фразы предложенные чатом не очень, поэтому нашёл джаз фразы в дорийском Ре; погонял Bubble Dream, чуть чище и расслабленнее получается'),
  ('6aa506ce-f710-4e6c-bb06-a9233b43b040'::uuid, '2025-09-16'::date, 80, E'Вечером залип за совместный трек с Лораном — Arcs, но снова застрял в творческом тупике'),
  ('ae553558-68c0-42ce-812a-4cd851050cbd'::uuid, '2025-09-17'::date, 50, E'Сделал необходимый минимум — было немного времени'),
  ('189aad4d-f2c1-4a29-8472-e561ef5b534a'::uuid, '2025-09-18'::date, 60, E'Гонял Вивальди'),
  ('1e6f95ec-e981-4d9b-af8e-130cffb9ac52'::uuid, '2025-09-19'::date, 60, E'На хроматике решил сделать шаг назад — с 90 на 80, а то пальцы путаются на 4-3-2-1'),
  ('3aff85a4-e813-456a-a9ba-c85634dea2c7'::uuid, '2025-09-20'::date, 30, E'Сегодня не очень идёт 1 во-первых, поздно сел (в половине восьмого); во-вторых настроение не очень после Миши'),
  ('25fc1bc4-0110-4463-b678-76d92cd87663'::uuid, '2025-09-21'::date, 130, E'Поджемил под Riders on the storm, стараюсь сначала представлять фразы на импровизации. Пока что всё равно больше вытягиваю фразы всё-таки из мышц.'),
  ('dc61fb3d-056d-4aa0-8c7c-0efa2041a73f'::uuid, '2025-09-22'::date, 75, E'Утром поимпровизировал поверх синтов и немного погонял Walking Wind'),
  ('2745dc89-ae45-47f9-adb9-fcb24311b075'::uuid, '2025-09-23'::date, 120, E'Walking Wind is cooking big time!'),
  ('94ebdb60-7872-4fc4-afad-b9107d1ccfbc'::uuid, '2025-09-24'::date, 70, E'Попробовал новую постановку левой руки — блюзовая или анатомически верная. Непривычно, но что-то в этом есть'),
  ('1b56ef1f-8ac5-4a88-bb70-f84f9ef48131'::uuid, '2025-09-25'::date, 85, E'Тупое говно тупого говна. Нужно какое-то разнообразие'),
  ('e2e26ad5-c50b-42d1-bd89-a46fdf9ad54c'::uuid, '2025-09-26'::date, 30, E'Совсем небольшая практика вечером перед сном'),
  ('9a97e4b6-8a92-4436-9004-bd5b5331bdcd'::uuid, '2025-09-27'::date, 15, E'Было только совсем немного времени вечером'),
  ('309e9465-0c10-4afc-a43c-2369137e79f8'::uuid, '2025-09-28'::date, 25, E'Снова не было времени. Попрактиковал low gain соло на Heroes'),
